// #2a8411 מסך ניהול משתמשים בחברה — только пользователи своей компании (AC6). Кейс: .qa/tests/company-users/CU-07.
// Две роли, каждая в своём окне (asUser). Только чтение.
import { test, expect } from '../../fixtures';
import { openUsers, readRows } from './users-page';

test('רשימת המשתמשים כוללת רק משתמשי החברה — A ו-B לא רואות זו את זו #2a8411 @desktop @prod-safe', async ({ asUser }) => {
  const adminA = await asUser('admin');
  const adminB = await asUser('admin2');

  await openUsers(adminA);
  await expect(adminA.getByRole('main').getByText('מי יכול לעבוד על מכרזים בחשבון QA Test בע"מ.', { exact: true })).toBeVisible();
  const emailsA = (await readRows(adminA)).map((r) => r.email.toLowerCase());

  await openUsers(adminB);
  await expect(adminB.getByRole('main').getByText('מי יכול לעבוד על מכרזים בחשבון QA Company B.', { exact: true })).toBeVisible();
  const emailsB = (await readRows(adminB)).map((r) => r.email.toLowerCase());

  expect(emailsA.length).toBeGreaterThan(0);
  expect(emailsB.length).toBeGreaterThan(0);
  expect(emailsA.filter((e) => emailsB.includes(e)), 'общие email у компаний A и B').toEqual([]);

  // Явно: в таблице B нет ни одного email компании A, и наоборот.
  for (const e of emailsA) await expect(adminB.getByRole('cell', { name: e, exact: true })).toHaveCount(0);
  for (const e of emailsB) await expect(adminA.getByRole('cell', { name: e, exact: true })).toHaveCount(0);
});
